"""Every rounding rule of meterbill lives here (see docs/rounding.md).

The arithmetic is done on integers, so nothing depends on the decimal context.
"""

from __future__ import annotations

import math
from decimal import Decimal

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _parts(d: Decimal) -> tuple:
    """(sign, coefficient, exponent) of a finite decimal."""
    sign, digits, exp = d.as_tuple()
    return sign, int("".join(map(str, digits)) or "0"), exp


def _make(sign: int, coefficient: int, exp: int) -> Decimal:
    return Decimal((sign, tuple(int(c) for c in str(coefficient)), exp))


def _add(a: Decimal, b: Decimal) -> Decimal:
    """Exact sum; the sign of a zero sum follows the decimal rules."""
    sa, ca, ea = _parts(a)
    sb, cb, eb = _parts(b)
    exp = min(ea, eb)
    total = (-ca if sa else ca) * 10 ** (ea - exp) + (-cb if sb else cb) * 10 ** (eb - exp)
    if total == 0:
        return _make(1 if sa and sb else 0, 0, exp)
    return _make(1 if total < 0 else 0, abs(total), exp)


def _sum(values, start: Decimal) -> Decimal:
    total = start
    for v in values:
        total = _add(total, v)
    return total


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    """The multiple of `step` nearest to `value`, ties and direction by `method`."""
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method {method!r}")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be positive")
    if not value.is_finite():
        raise ValueError("value must be finite")
    sign, coefficient, exp = _parts(value)
    _, unit, step_exp = _parts(step)
    low = min(exp, step_exp)
    numerator = coefficient * 10 ** (exp - low)
    denominator = unit * 10 ** (step_exp - low)
    count, rest = divmod(numerator, denominator)
    if method == HALF_UP:
        if 2 * rest >= denominator:
            count += 1
    elif method == HALF_EVEN:
        if 2 * rest > denominator or (2 * rest == denominator and count % 2 == 1):
            count += 1
    return _make(sign, count * unit, step_exp)


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    """One part per amount, cut down to `step`; the difference to the rounded
    total goes on the last amount that is not zero."""
    parts = [round_amount(a, step, DOWN) for a in amounts]
    whole = round_amount(_sum(amounts, Decimal("0")), step, HALF_UP)
    rest = _add(whole, _sum(parts, _make(0, 0, _parts(step)[2])).copy_negate())
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] = _add(parts[i], rest)
            break
    return parts


def legacy_cents(value: float, places: int = 2) -> float:
    """A float settled the way the old customer system did, in binary floating point."""
    scale = 10 ** places
    return math.floor(value * scale + 0.5) / scale


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    """`value` written with `places` digits after the point."""
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method {method!r}")
    if isinstance(value, Decimal):
        if not value.is_finite():
            return format(value, f".{places}f")
        step = _make(0, 1, -places)
        return format(round_amount(value, step, method), "f")
    if method != HALF_EVEN:
        raise ValueError("a float is only written half to even")
    return format(value, f".{places}f")
EOF

