    tf=d+"/t.json"; json.dump(tar,open(tf,"w"))
    ad=d+"/acc"; os.mkdir(ad)
    for a in range(6):
        acc={"account":f"A{a}","tariff":f"t{random.randint(0,1)}","period":{"start":"2026-03-01","end":f"2026-03-{random.randint(1,31):02d}"},
         "readings":[{"meter":"M","kwh":dec()} for _ in range(random.randint(0,3))],
         "credits":[{"ref":"c","amount":random.choice([-4.25,0.125,1.005,2.675,-0.005,-0.001,0.5,1e-9,3,random.uniform(-9,9)])} for _ in range(random.randint(0,3))]}
        if random.random()<.5:
            acc["standing"]=[{"from":"2026-03-01","to":f"2026-03-{random.randint(1,5):02d}","rate":random.choice(["0.125","0.0005","-0.001","0","0.3333","0.4110"])},{"from":"2026-03-06","to":"2026-03-10","rate":random.choice(["0.125","0.0005","0","0.3333","-0.004"])}]
        json.dump(acc,open(f"{ad}/a{a}.json","w"))
    cmds=[["--tariffs",tf,"tariffs"],["--tariffs",tf,"batch",ad],["--tariffs",tf,"batch",ad,"--format","csv"]]
    for a in range(6):
        for f in ["text","csv","json"]: cmds.append(["--tariffs",tf,"bill",f"{ad}/a{a}.json","--format",f])
    for _ in range(6):
        for f in ["text","json"]: cmds.append(["--tariffs",tf,"quote",f"t{random.randint(0,1)}",dec(),str(random.randint(1,40)),"--format",f])
    for c in cmds:
        if run("/tmp/orig",c)!=run("/app",c): bad+=1; print("DIFF",c)
print("bad",bad)
